import { readFile, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { renderChartKindPreviews } from "../../../packages/app/src/ui/examples/render-chart-kind-preview";

async function main(): Promise<void> {
  const previews = await renderChartKindPreviews();
  const generated = Object.fromEntries(previews.map((preview) => [preview.exampleId, preview]));
  const moduleSource = [
    "// This file is auto-generated by apps/web/scripts/generate-chart-kind-previews.ts.",
    "// Do not edit it manually.",
    "",
    "import type { GeneratedOpenExamplePreview } from \"./generated-open-example-previews\";",
    "",
    `export const GENERATED_CHART_KIND_PREVIEWS: Record<string, GeneratedOpenExamplePreview> = ${JSON.stringify(generated, null, 2)};`,
    ""
  ].join("\n");

  const thisDir = dirname(fileURLToPath(import.meta.url));
  const outputPath = resolve(thisDir, "../../../packages/app/src/ui/examples/generated-chart-kind-previews.ts");
  let previous: string | null = null;
  try {
    previous = await readFile(outputPath, "utf8");
  } catch {
    previous = null;
  }
  if (previous === moduleSource) {
    console.log("[chart-kind-previews] up to date");
    return;
  }
  await writeFile(outputPath, moduleSource, "utf8");
  console.log("[chart-kind-previews] wrote", outputPath);
}

void main().catch((error) => {
  console.error("[chart-kind-previews] generation failed:", error);
  process.exitCode = 1;
});
